 3	import { useTranslations, useLocale } from 'next-intl';
 4	import { useParams } from 'next/navigation';
 5	import { Link, usePathname, useRouter } from 'modules/i18n/utils/navigation';
 6	import Image from 'next/image';
 7	import { cn } from 'lib/utils';
 8	
 9	const NAV_ITEMS = [
10	  { href: '/' as const, key: 'home' },
11	  { href: '/services' as const, key: 'services' },
12	  { href: '/projects' as const, key: 'projects' },
13	  { href: '/team' as const, key: 'team' },
14	  { href: '/about' as const, key: 'about' },
15	  { href: '/contact' as const, key: 'contact' },
16	] satisfies Array<{
17	  href: '/' | '/services' | '/projects' | '/team' | '/about' | '/contact';
18	  key: string;
19	}>;
20	
21	export function Nav() {
22	  const t = useTranslations('Nav');
23	  const locale = useLocale();
24	  const pathname = usePathname();
25	  const params = useParams();
26	  const router = useRouter();
27	
28	  function switchLocale(next: string) {
29	    const href = (
30	      params && Object.keys(params).length > 0 ? { pathname, params } : pathname
31	    ) as any;
32	    router.replace(href, { locale: next });
33	  }
34	
35	  function isActive(href: string) {
36	    if (href === '/') return pathname === '/';
37	    return pathname.startsWith(href);
38	  }
39	
40	  return (
41	    <header className="sticky top-0 z-50 border-b border-rule bg-paper/85 backdrop-blur-[8px] backdrop-saturate-[140%]">
42	      <div className="max-w-[1440px] mx-auto px-[clamp(20px,4vw,64px)] py-[18px] flex items-center justify-between gap-8">
43	        <Link href="/" className="flex items-center gap-[10px]" aria-label="Hidroing">
44	          <Image
45	            src="/images/hidroing.png"
46	            alt="Hidroing"
47	            width={100}
48	            height={100}
49	          />
50	        </Link>
51	
52	        <nav className="hidden md:flex items-center gap-8 text-[14px] font-medium tracking-[-0.01em]" aria-label="Primary">
53	          {NAV_ITEMS.map((item) => (
54	            <Link
55	              key={item.key}
56	              href={item.href}
57	              className={cn(
58	                'relative py-[6px] text-ink-2 transition-colors duration-150 hover:text-ink',
59	                isActive(item.href) && 'text-ink after:absolute after:left-0 after:right-0 after:bottom-[-2px] after:h-px after:bg-green'
60	              )}>
61	              {t(item.key)}
62	            </Link>
63	          ))}
64	        </nav>
65	
66	        <div className="flex items-center gap-[18px]">
67	          <div
68	            className="inline-flex items-center border border-rule rounded-full p-[3px] bg-white font-mono text-[11px] tracking-[0.08em]"
69	            role="group"
70	            aria-label="Language">
71	            <button
72	              onClick={() => switchLocale('hr')}
73	              className={cn(
74	                'px-[10px] py-[5px] rounded-full cursor-pointer border-0 font-mono text-[11px] tracking-[0.08em] transition-none',
75	                locale === 'hr' ? 'bg-ink text-paper' : 'bg-transparent text-ink-3'
76	              )}>
77	              HR
78	            </button>
79	            <button
80	              onClick={() => switchLocale('en')}
81	              className={cn(
82	                'px-[10px] py-[5px] rounded-full cursor-pointer border-0 font-mono text-[11px] tracking-[0.08em] transition-none',
83	                locale === 'en' ? 'bg-ink text-paper' : 'bg-transparent text-ink-3'
84	              )}>
85	              EN
86	            </button>
87	          </div>
88	        </div>
89	      </div>
90	    </header>
91	  );
92	}

