    --spacing-32: 32px;
    --spacing-36: 36px;
    --spacing-40: 40px;
    --spacing-44: 44px;
    --spacing-48: 48px;
    --spacing-52: 52px;
    --spacing-56: 56px;
    --spacing-60: 60px;
    --spacing-64: 64px;
    --spacing-72: 72px;
    --spacing-80: 80px;
    --spacing-96: 96px;
    --spacing-100: 100px;
    --spacing-px: 1px;
    --spacing-0_5: 0.5px;
    --spacing-1_5: 1.5px;
    --spacing-2_5: 2.5px;
    --spacing-3_5: 3.5px;
}

@layer base {
    *,
    ::after,
    ::before,
    ::backdrop,
    ::file-selector-button {
        border-color: var(--color-gray-200, currentcolor);
    }

    html, body {
        @apply bg-paper text-ink font-sans;
        font-feature-settings: "ss01", "cv11", "tnum";
        -webkit-font-smoothing: antialiased;
    }

    a {
        @apply text-inherit no-underline;
    }

    img {
        display: block;
        max-width: 100%;
    }

    code {
        @apply bg-gray-5 rounded-md px-4 py-2;
    }
}
